//! The randomized deterministic corpus differential.
//!
//! The corpus is generated by a seeded linear congruential generator, so it
//! is identical on every run and on both sides. Every generated string, name
//! and endpoint is sent to the live Python oracle and to the native
//! implementation, and the results must match exactly.

mod support;

use kala_json::CanonicalValue;
use kala_runtime::gateway::{
    is_loopback_host, is_secret_name, normalize_endpoint, redact_secrets, truncate_encoded,
};

use support::{array, object, text};

/// A deterministic linear congruential generator.
struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        Self(seed)
    }

    fn next(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        self.0 >> 11
    }

    fn below(&mut self, bound: usize) -> usize {
        (self.next() % bound as u64) as usize
    }
}

