fn corpus() -> CanonicalValue {
    let mut rng = Rng::new(0x5EED_1234_ABCD_0001);
    let mut texts = Vec::new();
    for _ in 0..2_000 {
        let count = 1 + rng.below(6);
        let mut text = String::new();
        for _ in 0..count {
            text.push_str(FRAGMENTS[rng.below(FRAGMENTS.len())]);
        }
        texts.push(text);
    }
    let mut names = Vec::new();
    for _ in 0..500 {
        let count = 1 + rng.below(3);
        let mut name = String::new();
        for _ in 0..count {
            name.push_str(NAMES[rng.below(NAMES.len())]);
        }
        names.push(name);
    }
    let mut endpoints = Vec::new();
    for _ in 0..500 {
        let count = 1 + rng.below(3);
        let mut endpoint = String::new();
        for _ in 0..count {
            endpoint.push_str(ENDPOINTS[rng.below(ENDPOINTS.len())]);
        }
        endpoints.push(endpoint);
    }
    let mut decimals = Vec::new();
    for left in DECIMALS {
        for right in DECIMALS {
            decimals.push(object(vec![("left", text(left)), ("right", text(right))]));
        }
    }
    object(vec![
        ("decimals", array(decimals)),
        (
            "texts",
            array(texts.into_iter().map(|value| text(&value)).collect()),
        ),
        (
            "names",
            array(names.into_iter().map(|value| text(&value)).collect()),
        ),
        (
            "endpoints",
            array(endpoints.into_iter().map(|value| text(&value)).collect()),
        ),
    ])
}

#[test]
fn the_randomized_corpus_matches_the_python_gateway() {
    let document = corpus();
    let oracle = run_oracle_corpus(&document);

    let texts = array_of(&document, "texts");
    let names = array_of(&document, "names");
    let endpoints = array_of(&document, "endpoints");

    let mut redactions = Vec::new();
    for item in &texts {
        let value = item.as_text().expect("a text").to_string_lossy();
        let (redacted, findings) = redact_secrets(&value);
        redactions.push(object(vec![
            ("text", text(&value)),
            ("redacted", text(&redacted)),
            ("findings", CanonicalValue::integer(findings as i64)),
            ("truncated", text(&truncate_encoded(&value, 64))),
        ]));
    }
    let mut names_result = Vec::new();
    for item in &names {
        let value = item.as_text().expect("a name").to_string_lossy();
        names_result.push(object(vec![
            ("name", text(&value)),
            ("secret", CanonicalValue::Bool(is_secret_name(&value))),
        ]));
    }
    let mut endpoints_result = Vec::new();
    for item in &endpoints {
        let value = item.as_text().expect("an endpoint").to_string_lossy();
        match normalize_endpoint(&value, &[], false) {
            Ok(normalized) => {
                let host = normalized
                    .split("://")
                    .nth(1)
                    .and_then(|rest| rest.split(':').next())
                    .unwrap_or_default();
                endpoints_result.push(object(vec![
                    ("value", text(&value)),
                    ("normalized", text(&normalized)),
                    ("loopback", CanonicalValue::Bool(is_loopback_host(host))),
                ]));
            }
            Err(error) => endpoints_result.push(object(vec![
                ("value", text(&value)),
                ("error", text(error.message())),
            ])),
        }
    }
    let mut decimals = Vec::new();
    for item in array_of(&document, "decimals") {
        let left = support::text_field(&item, "left");
        let right = support::text_field(&item, "right");
        let left_value = kala_budget::Decimal::parse(&left).expect("a decimal");
        let right_value = kala_budget::Decimal::parse(&right).expect("a decimal");
        let product = kala_runtime::gateway::multiply(&left_value, &right_value)
            .map(|value| value.to_python_string())
            .unwrap_or_else(|error| error.python_class_name().to_owned());
        let quotient = kala_runtime::gateway::divide(&left_value, &right_value)
            .map(|value| value.to_python_string())
            .unwrap_or_else(|error| error.python_class_name().to_owned());
        decimals.push(object(vec![
            ("left", text(&left)),
            ("right", text(&right)),
            ("product", text(&product)),
            ("quotient", text(&quotient)),
        ]));
    }
    let native = object(vec![
        ("redactions", array(redactions)),
        ("names", array(names_result)),
        ("endpoints", array(endpoints_result)),
        ("decimals", array(decimals)),
    ]);
    let native_bytes = kala_json::canonical_json_dumps(&native).expect("canonical value");
    let oracle_bytes = kala_json::canonical_json_dumps(&oracle).expect("canonical value");
    if std::env::var("KALA_RUNTIME_DIFF_DUMP").is_ok() {
        std::fs::write("/tmp/kala-runtime-corpus-native.json", &native_bytes).expect("dump");
        std::fs::write("/tmp/kala-runtime-corpus-oracle.json", &oracle_bytes).expect("dump");
    }
    if native_bytes != oracle_bytes {
        panic!("the randomized corpus differs\nnative:\n{native_bytes}\noracle:\n{oracle_bytes}");
    }
}

/// One array field of the corpus document.
fn array_of(document: &CanonicalValue, key: &str) -> Vec<CanonicalValue> {
    match support::get(document, key) {
        Some(CanonicalValue::Array(values)) => values.clone(),
        _ => panic!("{key} is an array"),
    }
}

/// Run the corpus mode of the Python oracle.
fn run_oracle_corpus(scenario: &CanonicalValue) -> CanonicalValue {
    let script = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/oracle.py");
    let mut command = std::process::Command::new(support::python_executable());
    command
        .arg(script)
        .arg("corpus")
        .env(
            "PYTHONPATH",
            support::repo_root()
                .join("src")
                .to_string_lossy()
                .to_string(),
        )
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = command.spawn().expect("spawn the Python oracle");
    let payload = kala_json::canonical_json_dumps(scenario).expect("canonical scenario");
    {
        use std::io::Write as _;
        child
            .stdin
            .take()
            .expect("stdin")
            .write_all(payload.as_bytes())
            .expect("write the corpus");
    }
    let output = child.wait_with_output().expect("wait for the oracle");
    assert!(
        output.status.success(),
        "the Python corpus oracle failed with {:?}\n{}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    support::parse(&String::from_utf8(output.stdout).expect("the oracle stdout is UTF-8"))
}
